// Node.js — pasang SEBELUM require framework lain!
// (agent harus dimuat pertama agar bisa meng-instrumentasi Express)
require('elastic-apm-node').start({
  serviceName: 'api-gateway',
  serverUrl: 'http://apm-server:8200',
  environment: 'production',
  transactionSampleRate: 0.1,   // simpan 10% transaction lengkap
  captureExceptions: true,
})

const express = require('express')
const app = express()
app.get('/api/orders', (req, res) => {
  // Custom span: tandai blok kode penting secara manual
  const span = require('elastic-apm-node').startSpan('fetch-orders-db')
  // ... query database ...
  if (span) span.end()
  res.json({ orders: [] })
})
